// Exhaustively test prototype pollution vectors for lodash 4.17.20 _.merge
const _ = require("lodash");
console.log("lodash version:", _.VERSION);

const vectors = [
  '{"__proto__":{"pp1":1}}',
  '{"constructor":{"prototype":{"pp2":1}}}',
  '{"constructor":{"prototype":{}}}',  // noop
  '{"a":{"__proto__":{"pp3":1}}}',
  '{"a":{"constructor":{"prototype":{"pp4":1}}}}',
];

for (const v of vectors) {
  const parsed = JSON.parse(v);
  const target = {};
  try {
    _.merge({}, target, parsed);
  } catch (e) { console.log("err", e.message); }
  console.log(v, "=> pp1:", ({}).pp1, "pp2:", ({}).pp2, "pp3:", ({}).pp3, "pp4:", ({}).pp4);
  // reset
  delete Object.prototype.pp1;
  delete Object.prototype.pp2;
  delete Object.prototype.pp3;
  delete Object.prototype.pp4;
}

// Also test mergePreferences wrapper from the app
const { mergePreferences } = require("./src/utils/object");
const inp = JSON.parse('{"__proto__":{"ppw":99}}');
mergePreferences({ theme: "dark" }, inp);
